import re

def validate_credit_card(card_number):
    return bool(re.match(r'^\d{16}$', card_number))

def validate_phone_number(phone_number):
    return bool(re.match(r'^\d{1,3}-\d{3}-\d{3}$', phone_number))

# Test the validation functions
print(validate_credit_card("1234123412341234"))  # Expected: True
print(validate_credit_card("1234-1234-1234-1234"))  # Expected: False
print(validate_phone_number("1-100-111"))  # Expected: True
